def recipient_ok(address, allowed_domains):
    if address.count('@') != 1:
        return False
    local, domain = address.split('@')
    return bool(local) and domain.lower() in {d.lower() for d in allowed_domains}

def guarded_call(name, args, tools, state, approve):
    def deny(reason):
        state['log'].append((name, 'denied: ' + reason))
        return None
    if name not in tools:
        return deny('not allowed')
    fn, high = tools[name]
    if high and state['tainted']:
        return deny('tainted')
    if high and not approve(name, args):
        return deny('rejected')
    result = fn(**args)
    state['log'].append((name, 'ok'))
    return result

