st = {'tainted': False, 'log': []}
r = guarded_call('read', {'x': 2}, {'read': (lambda x: x + 1, False)}, st, lambda n, a: False)
assert r == 3 and st['log'] == [('read', 'ok')], (r, st)

sent = []
st = {'tainted': False, 'log': []}
t = {'send': (lambda: sent.append(1), True)}
guarded_call('send', {}, t, st, lambda n, a: False)
guarded_call('rm', {}, t, st, lambda n, a: True)
assert sent == [] and st['log'] == [('send', 'denied: rejected'), ('rm', 'denied: not allowed')], st['log']

