def audit_violations(events):
    available = {}
    bad = set()
    for e in events:
        cid = e['call_id']
        if e['type'] == 'approval' and e.get('approved'):
            available[cid] = available.get(cid, 0) + 1
        elif e['type'] == 'exec' and e.get('high_impact'):
            if available.get(cid, 0) > 0:
                available[cid] -= 1
            else:
                bad.add(cid)
    return sorted(bad)
